import{_ as t,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const l=JSON.parse('{"title":"🔬 科学日报 | 2026年10月8日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-10-08.md","filePath":"science-log/src/science-daily/2026-10-08.md"}'),g={name:"science-log/src/science-daily/2026-10-08.md"};function e(a,o,i,c,d,u){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="🔬-科学日报-2026年10月8日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年10月8日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年10月8日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年10月8日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第31期简讯（🔬 科学前沿 5 篇 / 🤖 AI前沿 5 篇，共 10 条） 分析日期：2026-10-08 版本：扩展版（10 条深度 + 交叉关联） 核查说明：本期 <strong>6 篇期刊论文的 DOI + 4 篇 arXiv 预印本均于 2026-11-05 逐条联网核验通过</strong>——期刊条目用 <strong>CrossRef API</strong>（<code>api.crossref.org/works/&lt;DOI&gt;</code>，直连即通），预印本用 <strong>arXiv API</strong>（<code>export.arxiv.org/api/query?id_list=</code>）。作者、期刊、年份均取自 API 返回值。机制与因果链描述以当天简讯（第31期）为唯一依据，凡简讯未给出者不补充、不推测。</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-首个闭环运行的钍-229-核光钟" tabindex="-1">1. 首个闭环运行的钍-229 核光钟 <a class="header-anchor" href="#_1-首个闭环运行的钍-229-核光钟" aria-label="Permalink to &quot;1. 首个闭环运行的钍-229 核光钟&quot;">​</a></h3><p><strong>原文</strong>：钍-229 原子核的 148 nm 核跃迁因可用激光直接激发，被认为是比电子壳层光钟更抗外界扰动、对基础物理检验更敏感的候选时间基准。</p><p><strong>深度扩展</strong>：该研究由 Toscani De Col 等（共 28 位作者）完成，2026 年 10 月 8 日发表于《Nature》（DOI: 10.1038/s41586-026-11084-4）。核光钟的根本优势，在于把&quot;计时基准&quot;从原子<strong>电子壳层</strong>的跃迁，换到原子核<strong>内部</strong>的跃迁：²²⁹Th 存在一条能量约 8.4 eV（对应 148 nm 真空紫外）的核同质异能跃迁，能量之低恰好可用激光直接驱动——这在所有原子核中是独一无二的。相比电子壳层，核跃迁的能级对环境电场、磁场、温度扰动远不敏感，因此既更稳，也对&quot;基础常数是否在漂移&quot;更敏感。团队的关键动作有三重：其一，把连续波激光的频率<strong>直接锁定</strong>到嵌在毫米级<strong>室温 CaF₂ 晶体</strong>中的 ²²⁹Th 跃迁上，而不是依赖复杂昂贵的离子阱＋冷却，室温固体环境把工程门槛大幅拉低；其二，用基于<strong>吸收光谱</strong>的快速反馈实现<strong>闭环运转</strong>——即用测得的跃迁吸收信号反过去纠稳激光频率，这正是&quot;带反馈环&quot;的实质；其三，把 148 nm 辐射的<strong>次谐波</strong>与一台成熟的<strong>镱离子（Yb⁺）单钟</strong>持续比对，用一个已校准的光钟去标定这个新钟。指标上，其分数频率不稳定度达到 <strong>3×10⁻¹²/√(τ/s)</strong>，积分运行一天可逼近 <strong>10⁻¹⁵</strong>。团队还把它当作一台<strong>超轻暗物质探测器</strong>：若存在与核子耦合的超轻暗物质场，会以特征周期引起跃迁频率的周期漂移，而核钟正是最灵敏的&quot;天平&quot;之一。这是核光钟首次以<strong>带反馈环</strong>的方式稳定运转，把&quot;核钟&quot;从原理验证推进到可运行的精密测量平台，为下一代超高精度计时与基础常数检验打开了大门。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/science-daily-2026-10-08.md</code> 及 <code>topics/physics/index.md</code> 中&quot;精密测量作为基础物理探针&quot;的主线同构——<strong>都是用&quot;频差&quot;这一极高信噪比的观测量，去搜索极微弱的新物理耦合</strong>。</p><hr><h3 id="_2-相对论让最近超重元素的金属—配体键变弱" tabindex="-1">2. 相对论让最近超重元素的金属—配体键变弱 <a class="header-anchor" href="#_2-相对论让最近超重元素的金属—配体键变弱" aria-label="Permalink to &quot;2. 相对论让最近超重元素的金属—配体键变弱&quot;">​</a></h3><p><strong>原文</strong>：超重元素（Z ≥ 104）的化学性质深受相对论效应影响其价电子壳层，理论预测其羰基配合物的金属—配体键稳定性会被改变，但一直缺乏直接实验证据。</p><p><strong>深度扩展</strong>：该研究由 Yakushev 等（共 24 位作者）完成，2026 年 10 月 8 日发表于《Nature》（DOI: 10.1038/s41586-026-11105-2）。这是典型的<strong>单原子化学</strong>实验：超重元素只能由核反应一次一个原子地合成，产量极低、寿命以秒计，无法用常规化学称量。团队用<strong>气相色谱</strong>来&quot;称量&quot;键的强弱——让单个 Sg(CO)₆ 分子在充满载气的色谱柱中迁移，其保留行为取决于分子稳定性；通过测量 Sg(CO)₆ 相对已知同族物 <strong>W(CO)₆</strong> 的<strong>生成产率</strong>，反推出 Sg(CO)₆ 的<strong>第一键解离能</strong>为 <strong>188(9) kJ·mol⁻¹</strong>，比 W(CO)₆ <strong>低 4(2) kJ·mol⁻¹</strong>。这一负号才是要害：第 6 族六羰基物的键解离能本应&quot;随原子序数增大（Mo→W）而递增&quot;，此趋势却在 <strong>W→Sg</strong> 处<strong>被逆转</strong>。原因在于相对论效应：核电荷极大的 Sg 中，内层电子高速运动、s 轨道显著收缩，连带把 <strong>6d 价轨道相对论去稳定（能级抬高）</strong>，使金属 d 轨道与 CO 的配体轨道交叠变差、金属—配体键变弱。该结果与最先进的理论计算一致，是超重元素成键中<strong>相对论效应</strong>的一次干净实验验证——它说明元素周期表底部那些&quot;看起来该延续的趋势&quot;，会被狭义相对论本身打断。</p><p><strong>跨主题关联</strong>：与 <code>topics/physics/index.md</code>（重元素/相对论效应）及 <code>topics/materials/index.md</code> 中&quot;微观成键决定宏观性质&quot;的主线呼应：<strong>宏观性质的异常，追到最底层是相对论在价电子轨道上的几何后果</strong>。</p><hr><h3 id="_3-带隙突破-7-ev-硅掺杂-α-alxga1−x-2o3-半导体" tabindex="-1">3. 带隙突破 7 eV：硅掺杂 α-(AlₓGa₁₋ₓ)₂O₃ 半导体 <a class="header-anchor" href="#_3-带隙突破-7-ev-硅掺杂-α-alxga1−x-2o3-半导体" aria-label="Permalink to &quot;3. 带隙突破 7 eV：硅掺杂 α-(AlₓGa₁₋ₓ)₂O₃ 半导体&quot;">​</a></h3><p><strong>原文</strong>：在功率电子中，带隙越宽器件效率与功率密度越高（Baliga 优值正比于 Eg^5.5），但带隙越大就越难用平衡掺杂把电导率可控地调制几个数量级——这长期是超宽带隙半导体的核心瓶颈。</p><p><strong>深度扩展</strong>：该研究由 Steele 等（共 20 位作者）完成，2026 年 10 月 8 日发表于《Nature》（DOI: 10.1038/s41586-026-11085-3）。功率半导体的&quot;性能上限&quot;由一个残酷的标度决定：<strong>Baliga 优值（衡量功率器件优度的指标）正比于带隙的 5.5 次方</strong>（Eg^5.5）——带隙每增大一点，理论击穿电压与功率密度就跃升一大截。这就是业界一直想往&quot;超宽带隙&quot;（Ultra-Wide-Bandgap）走的动力。但物理上没有免费午餐：带隙越大，杂质电离能越深、载流子越难被热激发，用<strong>平衡掺杂</strong>把电导率可控地调节几个数量级就越是噩梦，这长期是超宽带隙半导体的死结。团队的做法是用<strong>亚氧化物分子束外延（suboxide MBE）<strong>生长</strong>硅掺杂</strong>的 <strong>α-(AlₓGa₁₋ₓ)₂O₃</strong> 薄膜——这是一族&quot;α 相氧化镓–氧化铝&quot;的连续固溶体，通过调 Al/Ga 比例可以把带隙连续调控。他们把带隙推到 <strong>&gt; 7.0 eV</strong>，一举超过此前公认最宽带的半导体<strong>立方氮化硼（c-BN）</strong>。真正的突破在于打破死结：在 <strong>&gt;6 eV 的&quot;巨大带隙（gigantic bandgap）&quot;区间</strong>，这些薄膜的<strong>室温电导率比以往同类材料高出逾一亿倍（10⁸）</strong>，证明&quot;大带隙未必等于无法调控导电性&quot;——Si 掺杂在该固溶体系中找到了可有效电离施主的窗口。这为高效、高功率密度的下一代功率器件（如更高压的电力电子、深紫外光电器件）提供了新的候选平台。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code>、<code>topics/materials/2026-q3-breakthroughs.md</code> 及 <code>topics/physics/advanced-materials-deep.md</code> 中&quot;用掺杂/固溶工程在极端参数区间实现可控功能&quot;的主线一致：<strong>瓶颈往往不是&#39;能不能做出来&#39;，而是&#39;能不能按需调制&#39;</strong>。</p><hr><h3 id="_4-随人类走出非洲、正在消失的肠道微生物" tabindex="-1">4. 随人类走出非洲、正在消失的肠道微生物 <a class="header-anchor" href="#_4-随人类走出非洲、正在消失的肠道微生物" aria-label="Permalink to &quot;4. 随人类走出非洲、正在消失的肠道微生物&quot;">​</a></h3><p><strong>原文</strong>：许多在非工业化人群中常见的肠道微生物，在工业化人群里已经消失或灭绝，但哪些是人类肠道的&quot;长期居民&quot;、是否与人类共同演化，此前难以厘清。</p><p><strong>深度扩展</strong>：该研究由 Carter 等（共 15 位作者）完成，2026 年 10 月 8 日发表于《Nature》（DOI: 10.1038/s41586-026-11106-1）。它要回答一个带演化色彩的问题：我们肠道里那些&quot;古老&quot;的微生物，是<strong>随人类一起走出非洲、与我们共同演化</strong>的长期居民，还是从环境或食物里反复捡来的&quot;过客&quot;？团队用两条几乎不接触现代工业生活的人群作为&quot;时间胶囊&quot;：玻利维亚的 <strong>Tsimane</strong> 农耕人群与坦桑尼亚的 <strong>Hadza</strong> 狩猎采集人群。这两支人群的祖先在地理与谱系上已分离<strong>数万年</strong>，如果某些微生物是人类的<strong>共进化共生体</strong>，那么它们应当在这两支&quot;已分离很久&quot;的人群中<strong>仍然共享</strong>。深度宏基因组测序给出的答案是肯定的：两个群体<strong>共享 1231 个微生物物种</strong>，而且其中<strong>大多数在工业化人群中罕见或已缺失</strong>。由于近万年内的水平传播难以解释跨越大洲、跨越数万年的稳定共存，最自然的解释是——这些物种是<strong>随人类迁徙而扩散、长期共居于人类肠道</strong>的&quot;原住民&quot;，它们与宿主一起经历了迁徙与演化。该研究为评估<strong>微生物多样性丧失</strong>（工业化生活方式导致的菌群&quot;贫化&quot;）如何影响现代人健康、以及<strong>重建人类—微生物共进化史</strong>，提供了关键的基线数据。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/2026-q3-breakthroughs.md</code> 中&quot;宿主–微生物互作决定健康&quot;的线索一致，也呼应 <code>topics/paleoanthropology/index.md</code> 的人类迁徙母题：<strong>现代疾病的一部分风险，可能刻在&#39;菌群随人走、却又被现代生活抹去&#39;这段历史里</strong>。</p><hr><h3 id="_5-侏罗纪一具会游泳的哺乳形动物-改写吞咽装置的起源" tabindex="-1">5. 侏罗纪一具会游泳的哺乳形动物，改写吞咽装置的起源 <a class="header-anchor" href="#_5-侏罗纪一具会游泳的哺乳形动物-改写吞咽装置的起源" aria-label="Permalink to &quot;5. 侏罗纪一具会游泳的哺乳形动物，改写吞咽装置的起源&quot;">​</a></h3><p><strong>原文</strong>：中国中侏罗世出土的一具保存精美的哺乳形动物化石，为理解哺乳动物摄食装置的演化与中生代哺乳形动物的生态多样性提供了直接证据。</p><p><strong>深度扩展</strong>：该研究由 Li 等（共 7 位作者）完成，2026 年 10 月 8 日发表于《Nature》（DOI: 10.1038/s41586-026-11107-0）。化石来自<strong>中国中侏罗世</strong>地层，且是一具保存得罕见的<strong>哺乳形动物（mammaliaform）<strong>标本。它的价值有两层。第一层是</strong>软组织解剖的复活</strong>：化石罕见地保存了类似<strong>兽亚纲的咽腔顶（咽喉通道）与舌骨（咽部骨骼）<strong>结构。吞咽、饮水与</strong>吮乳</strong>（哺乳动物的标志性行为）所需的正是这一套柔软、极难石化的咽部解剖；此前学界普遍认为这些特征随&quot;真哺乳动物&quot;兴起才出现，而这具化石提示——<strong>兽亚纲式的咽部装置，在齿兽类（Docodonta）与哺乳动物的共同祖先中就已经演化出来</strong>，时间上远早于现代哺乳动物的辐射。第二层是<strong>生态位信息</strong>：化石同时具备一系列<strong>适应游泳</strong>的骨骼特征（如特化的骨盆与后肢形态），填补了早期哺乳动物骨盆与后肢解剖的关键空白，表明中生代哺乳形动物早已&quot;下水&quot;、开拓了半水生生态位；其高度特化的<strong>犬齿与伪裂齿</strong>则指示<strong>食虫/食肉</strong>习性。综合起来，这具标本把&quot;哺乳动物的定义性行为（吮乳/吞咽）何时成型&quot;与&quot;早期哺乳形动物的生态多样性&quot;两个大问题同时往前推进：复杂的摄食装置并非哺乳动物的专利，而是更深层祖先的遗产。</p><p><strong>跨主题关联</strong>：与 <code>topics/paleontology/index.md</code>、<code>topics/paleontology/science-daily-2026-10-08.md</code> 及 <code>topics/paleoanthropology/index.md</code> 中的演化解剖母题直接相扣：<strong>关键功能往往先在&#39;非典型&#39;的祖先类群里出现，之后才在主流谱系里被发扬</strong>。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-把语言模型-改装-成按字节运行" tabindex="-1">6. 把语言模型&quot;改装&quot;成按字节运行 <a class="header-anchor" href="#_6-把语言模型-改装-成按字节运行" aria-label="Permalink to &quot;6. 把语言模型&quot;改装&quot;成按字节运行&quot;">​</a></h3><p><strong>原文</strong>：当今大语言模型普遍以子词（subword）分词把文本切分成 token，这层切分掩盖了细粒度字符信息，对代码、生物序列等&quot;意义依赖单个字符/字节&quot;的科学数据尤其不利；而直接按字节建模的模型此前性能一直落后于子词模型。</p><p><strong>深度扩展</strong>：该研究由 Minixhofer 等（共 9 位作者）完成，2026 年 10 月 8 日发表于《Nature》（DOI: 10.1038/s41586-026-11111-4）。它瞄准大语言模型一个被习惯掩盖的弱点：<strong>分词</strong>。当今 LLM 普遍先用 <strong>BPE 等子词算法</strong>把文本切成 token，模型只在 token 层面运算——这层切分带来两个代价：一是<strong>细粒度字符/字节信息被抹平</strong>（同一个 token 内部究竟由哪些字节组成，模型&quot;看不见&quot;）；二是<strong>词表与域强绑定</strong>（分子式、源代码、基因序列等&quot;意义依赖单个字符&quot;的科学数据，常常落到词表之外，被切得七零八落）。而直接用<strong>字节</strong>建模虽天然通用，历史性能却总落后子词模型一大截（序列变长、有效建模更难）。团队的贡献是把这件事&quot;<strong>改装（retrofit）</strong>&quot;掉：提出一种通用的<strong>字节化（byteification）<strong>方法，用</strong>两阶段转换流程</strong>把一个<strong>已有的子词模型</strong>改造成<strong>字节级模型</strong>，而且只需极少的额外训练——即不必从零重训，而是&quot;复用&quot;预训练模型已学到的知识，只把输入/输出接口换到字节粒度。改造后的字节级模型<strong>性能超过以往的字节级模型、逼近子词系统的能力</strong>。意义在于：它为源代码、基因序列这类<strong>结构本就以字符/字节为单位</strong>的科学数据，提供了不牺牲性能的建模基础，也让模型摆脱&quot;为每种模态重造分词器&quot;的负担。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-system-architecture/2026-h1-ai-landscape.md</code> 中&quot;模型能力取决于输入表示粒度&quot;的主线一致，也与 <code>topics/intelligence-self-learning/index.md</code> 的可迁移表征母题呼应：<strong>把表征粒度对齐到数据的真实语义单位，往往比堆参数更有效</strong>。</p><hr>',35)])])}const p=t(g,[["render",e]]);export{l as __pageData,p as default};
